Hypothesis A10 : getr R 10%bv = Z_to_bv 64 (fb + 440).
Hypothesis CPRE : PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M fb p X s str sm en k e cat.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis POK : PECS.payload_ok p.
Hypothesis MP : PECS.mp_enc p X.
Hypothesis HB : PESK.sp_hb P (xhi + 9).
Hypothesis CRED : PMSP.credit_le (PEC.pot_enc L P en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model)
            (en' : PEC.enc) (k' : PESK.sink) (e' : bool) (cr' : credit) (w : Z),
        regs_preserved R R' -> (w = 5 \/ w = 9) ->
        PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M' fb p (e_end_value (XS w)) s str sm en' k' e' cat -> (e = true -> e' = true) ->
        L5C.hpres L (PM.parser_own s ++ LBX) sp (PMSP.pm_scr 4) (PEC.W_enc CAD EE fb) M M' ->
        PMSP.credit_keep cr cr' (PEC.pot_enc L P en k) (PEC.pot_enc L P en' k') ->
        model_but_vm model model' -> hi_heap HI (PEC.owned s en' k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

